package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class WorkSearchAcceptance {
 static String seed(Store store,String key) throws Exception {try(var db=store.open()){String actor=PlatformFoundationTest.bind(db),job=WorkJobs.enqueue(store,db,actor,map("kind","notification","key",key,"payload",map("username","admin","message","PAYLOAD SECRET"))).get("job_id").toString();db.connection.commit();return job;}}
 static Map<String,Object> result(WorkflowSupport h,String query) throws Exception {var response=h.get("/api/openservice/job-search"+query,auth("admin"));assertEquals(200,response.statusCode(),html(response));return parsed(response);}
 static void run(WorkflowSupport h) throws Exception {
  h.account("WorkReader","reader");String special=seed(h.store,"Literal 100%_! <script>");for(int i=0;i<101;i++)seed(h.store,"ordinary-"+i);
  var first=result(h,"");assertEquals(102,first.get("total"));assertEquals(100,objects(first.get("result")).size());assertEquals(100,first.get("next_offset"));var second=result(h,"?offset=100");assertEquals(2,objects(second.get("result")).size());assertEquals(-1,second.get("next_offset"));assertFalse(JSON.writeValueAsString(first).contains("PAYLOAD SECRET"));assertEquals(0,result(h,"?q=PAYLOAD%20SECRET").get("total"));assertEquals(1,result(h,"?q=100%25_%21").get("total"));assertEquals(1,result(h,"?q="+special).get("total"));assertEquals(102,result(h,"?kind=notification&state=queued").get("total"));assertEquals(0,result(h,"?kind=connector.read").get("total"));
  for(String bad:List.of("limit=0","limit=101","offset=-1","state=bad","kind=bad","extra=x","q=a&q=b","q="+"x".repeat(201),"q=%00"))assertEquals(400,h.get("/api/openservice/job-search?"+bad,auth("admin")).statusCode());assertEquals(403,h.get("/admin/jobs",auth("WorkReader")).statusCode());assertEquals(401,h.get("/api/openservice/job-search",null).statusCode());assertEquals(405,h.json("POST","/api/openservice/job-search",map(),auth("admin")).statusCode());
  var form=map("job_id",special,"operation","cancel","q","100%_!","kind","all","state","all","offset","0","limit","1");assertEquals(403,h.form("/admin/jobs",form,auth("admin")).statusCode());form.put("limit","bad");assertEquals(400,h.protectedForm("/admin/jobs",form,auth("admin")).statusCode());assertEquals(1,result(h,"?q="+special+"&state=queued").get("total"));form.put("limit","1");form.put("operation","cleanup");assertEquals(400,h.protectedForm("/admin/jobs",form,auth("admin")).statusCode());form.put("operation","retry");assertEquals(200,h.protectedForm("/admin/jobs",form,auth("admin")).statusCode());form.put("operation","cancel");assertEquals(200,h.protectedForm("/admin/jobs",form,auth("admin")).statusCode());assertEquals(1,result(h,"?q="+special+"&state=cancelled").get("total"));assertEquals(400,h.protectedForm("/admin/jobs",form,auth("admin")).statusCode());
  String processing=seed(h.store,"processing-item"),failed=seed(h.store,"failed-item");DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_work SET state='processing' WHERE job_id=?",processing);DiverseBatchAcceptance.fixtureUpdate(h,"UPDATE os_work SET state='failed',attempts=3,error='synthetic' WHERE job_id=?",failed);assertEquals(400,h.protectedForm("/admin/jobs",map("job_id",processing,"operation","cancel"),auth("admin")).statusCode());assertEquals(200,h.protectedForm("/admin/jobs",map("job_id",failed,"operation","retry"),auth("admin")).statusCode());try(var db=h.store.open()){var retried=db.one("SELECT state,attempts,error FROM os_work WHERE job_id=?",failed);assertEquals("queued",retried.get("state"));assertEquals(0,retried.get("attempts"));assertEquals("",retried.get("error"));}assertTrue(html(h.get("/admin/jobs?q=no-such-work",auth("admin"))).contains("No matching jobs"));
  assertEquals(400,h.protectedForm("/admin/jobs?q=x",form,auth("admin")).statusCode());assertEquals(403,h.protectedForm("/admin/jobs",form,auth("WorkReader")).statusCode());String detail="/admin/jobs/"+special;assertEquals(200,h.get(detail,auth("admin")).statusCode());assertEquals(403,h.get(detail,auth("WorkReader")).statusCode());assertEquals(404,h.get("/admin/jobs/"+id(),auth("admin")).statusCode());assertEquals(400,h.get(detail+"?x=y",auth("admin")).statusCode());assertEquals(405,h.protectedForm(detail,map(),auth("admin")).statusCode());
  try(var db=h.store.open()){db.update("UPDATE os_work SET result=? WHERE job_id=?",Outbox.encrypt(h.store.secret,JSON.writeValueAsString(map("receipt",map("delivered",true,"secret","HIDDEN RECEIPT")))),special);db.connection.commit();}String html=html(h.get(detail,auth("admin")));assertTrue(html.contains("delivered"));assertFalse(html.contains("HIDDEN RECEIPT"));
 }
}
